class Temperature:
    def __init__(self, c):
        self.c = c
    def __format__(self, format_spec):
        if format_spec == "f":
            return f"{self.c * 9/5 + 32:.1f}°F"
        return f"{self.c}°C"

t = Temperature(100)
print(f"{t:f}")

class DynamicRecord:
    def __init__(self, data):
        self.data = data
    def __getattr__(self, name):
        if name in self.data:
            return self.data[name]
        raise AttributeError(f"No attribute {name}")

dr = DynamicRecord({"status": "active"})
print(dr.status)

class DiscountStrategy:
    def apply(self, price):
        return price
class PercentageDiscount(DiscountStrategy):
    def apply(self, price):
        return price * 0.9

class ShoppingCart:
    def __init__(self, strategy=DiscountStrategy()):
        self.strategy = strategy
    def checkout(self, total):
        return self.strategy.apply(total)

cart = ShoppingCart(PercentageDiscount())
print(int(cart.checkout(200)))

class Resource:
    def __del__(self):
        print("Resource destroyed")

def scope():
    r = Resource()

scope()
